enum class SubmitError {
  InvalidShape, UnsupportedFormat, Full, Stopping
};
struct Accepted { std::uint64_t ticket; };
using SubmitResult = std::variant<Accepted, SubmitError>;

// Gray8 only; positive width, height, stride.
// min_bytes = (height - 1) * stride + width
// Check overflow BEFORE multiplication and addition.
// Require stride >= width, buffer.size() >= min_bytes.
// Accepted transfers ownership to the pipeline.

received = accepted + rejected
accepted = queued + running + succeeded
         + failed + cancelled + expired
rejected = full + invalid + stopping + duplicate

// Terminal states are mutually exclusive.
// Preview eviction after acceptance => expired.
// A hidden/stale UI result is a separate UI metric.
